// ── VIDEO DE RESEÑAS, ANTES DE LOS 7 PASOS ─────────────────────────────────────
// Oscar (11/08): "antes de enviar los pasos, haz tu pedido en 7 pasos, envía el
// salesbot de video reseña de confianza". En Kommo era el salesbot 62110; en GHL no
// hay salesbots, así que el paso no existía.
//
// Se dispara con el bloque de los 7 pasos, que es exactamente donde Oscar lo pidió, y
// se inserta DESPUÉS de las fichas de producto y ANTES del texto del agente.
//
// ⚠️ La cardinalidad va atada al mensaje de los 7 pasos: si el agente lo repitiera en
// una misma conversación, el video saldría de nuevo. El prompt del Recolector ya dice
// "no mandes reiteradas veces el mensaje de los 7 pasos", así que hoy no pasa; si
// alguna vez pasa, se arregla ahí y no acá.
const VIDEO_RESENAS = 'https://assets.cdn.filesafe.space/onRwi0ZF4uYi0Lp6GAbE/media/6a7e351ca6a03cda06c8508c.mp4';
const TEXTO_RESENAS = 'Sabemos que comprar por internet puede generar desconfianza… 😰\n\n'
  + 'Con HAPPY FLOPS, tienes la SEGURIDAD de que TODO es CONFIABLE, aquí puedes ver '
  + 'lo que dicen nuestros clientes en Facebook ⭐⭐⭐⭐⭐';
if (/7 SENCILLOS PASOS/i.test(txt)) {
  partesFinales.splice(fichasFinales.length, 0,
    { texto: TEXTO_RESENAS, adjuntos: [VIDEO_RESENAS] });
}

